  const n = big ? 10000 : r.int(1, 12);
  if (r.bool(0.5)) {
    const divs = [];
    for (let d = 1; d < n; d++) if (n % d === 0) divs.push(d);
    if (divs.length) {
      const d = big ? r.pick(divs.filter(x => x >= 100).concat([5000])) : r.pick(divs);
      let s = r.str(d, "ab").repeat(n / d);
      if (r.bool(0.3)) { const i = r.int(0, n - 1); s = s.slice(0, i) + (s[i] === "a" ? "b" : "a") + s.slice(i + 1); }
      return [s];
    }
  }
  return [r.str(n, big ? "a" : "ab").slice(0, n - 1) + r.pick(["a", "b"])];
}

