function isRepeatedBlock(s: string): boolean {
  const n = s.length;
  for (let d = 1; d <= n / 2; d++) {
    if (n % d !== 0) continue;
    let ok = true;
    for (let i = d; i < n && ok; i++) if (s[i] !== s[i - d]) ok = false;
    if (ok) return true;
  }
  return false;
}

